        var write = 1;
        var lastClass = CombiningClass(units[0]) != 0 ? 256 : 0;

        for (var read = 1; read < units.Count; read++)
        {
            var current = units[read];
            var currentClass = CombiningClass(current);
            if ((lastClass < currentClass || lastClass == 0)
                && TryCompose(units[starter], current, out var composed))
            {
                units[starter] = composed;
                continue;
            }

            if (currentClass == 0)
            {
                starter = write;
            }

            lastClass = currentClass;
            units[write++] = current;
        }

        units.RemoveRange(write, units.Count - write);
    }

    private static bool TryCompose(char first, char second, out char composed)
    {
        // Hangul syllable composition is arithmetic rather than table driven.
        var leading = first - HangulLBase;
        if (leading >= 0 && leading < HangulLCount)
        {
            var vowel = second - HangulVBase;
            if (vowel >= 0 && vowel < HangulVCount)
            {
                composed = (char)(HangulSBase + (((leading * HangulVCount) + vowel) * HangulTCount));
                return true;
            }
        }

        var syllable = first - HangulSBase;
        if (syllable >= 0 && syllable < HangulSCount && syllable % HangulTCount == 0)
        {
            var trailing = second - HangulTBase;
            if (trailing > 0 && trailing < HangulTCount)
            {
                composed = (char)(first + trailing);
                return true;
            }
        }

        return Compositions.TryGetValue((first << 16) | second, out composed);
    }

    private static int CombiningClass(char c) =>
        c < 0x0300 ? 0 : (CombiningClasses.TryGetValue(c, out var ccc) ? ccc : 0);

    private static Dictionary<int, char> BuildCompositions()
    {
        var map = new Dictionary<int, char>(CompositionData.Length / 3);
        for (var i = 0; i + 2 < CompositionData.Length; i += 3)
        {
            map[(CompositionData[i] << 16) | CompositionData[i + 1]] = CompositionData[i + 2];
        }

        return map;
    }

    private static Dictionary<char, byte> BuildCombiningClasses()
    {
        var map = new Dictionary<char, byte>(CombiningClassData.Length / 2);
        for (var i = 0; i + 1 < CombiningClassData.Length; i += 2)
        {
            map[CombiningClassData[i]] = (byte)CombiningClassData[i + 1];
        }

        return map;
    }

    private static Dictionary<char, char> BuildSingletons()
    {
        var map = new Dictionary<char, char>(SingletonData.Length / 2);
        for (var i = 0; i + 1 < SingletonData.Length; i += 2)
        {
            map[SingletonData[i]] = SingletonData[i + 1];
        }

        return map;
    }
}
